import type { WorkbenchService, WorkbenchSnapshot } from './Types.js';

export interface SyntheticOptions {
	mode?: 'normal' | 'empty' | 'error';
	long?: boolean;
}
/** Demonstration data only, deterministic dates/IDs and a real 100ms asynchronous read. */
export function createSyntheticService(
	options: () => SyntheticOptions = () => ({})
): WorkbenchService {
	let version = 0;
	return {
		async load({ signal, identity }) {
			const config = { ...options() };
			await new Promise<void>((resolve, reject) => {
				if (signal.aborted) {
					reject(new DOMException('读取已取消', 'AbortError'));
					return;
				}
				const cancel = () => {
					clearTimeout(timer);
					reject(new DOMException('读取已取消', 'AbortError'));
				};
				const timer = setTimeout(() => {
					signal.removeEventListener('abort', cancel);
					resolve();
				}, 100);
				signal.addEventListener('abort', cancel, { once: true });
			});
			if (config.mode === 'error') throw Error('合成服务暂时不可用，请重试读取');
			const long = config.long ? 'WorkspaceIdentityWithoutAnyWordBreak'.repeat(12) : '';
			const snapshot: WorkbenchSnapshot = {
				version: String(++version),
				workspace: {
					title: long || '今天，从清晰开始。',
					description: '关注团队进展，处理当前任务，快速到达常用工作。',
					name: long || `${identity} · 产品协作组`
				},
				metrics: [
					{
						id: 'tasks',
						label: '待办任务',
						value: 12,
						unit: '项',
						helper: '当前工作空间的任务快照',
						trend: {
							direction: 'down',
							tone: 'positive',
							value: 2,
							precision: 0,
							unit: '项',
							label: '较上次减少'
						}
					},
					{
						id: 'active',
						label: '进行中',
						value: 6,
						unit: '项',
						helper: '状态由工作空间服务提供'
					},
					{
						id: 'risk',
						label: '逾期任务',
						value: 0,
						unit: '项',
						helper: '0 为真实数值，未做缺省替换'
					},
					{
						id: 'capacity',
						label: '可用容量',
						value: null,
						unit: '小时',
						helper: '尚未提供容量数据'
					}
				],
				shortcuts: [
					['projects', '项目总览'],
					['documents', '团队资料'],
					['calendar', '计划日历'],
					['members', '团队成员'],
					['reports', '进展报告'],
					['requests', '需求中心'],
					['settings', '空间设置'],
					['archive', '项目归档']
				].map(([id, label]) => ({
					id: id!,
					label: label!,
					description: `打开${label}的工作页面`,
					target: id!,
					permission: `read:${id}`
				})),
				tasks: Array.from({ length: 12 }, (_, i) => ({
					id: i === 0 ? 0 : `task-${i + 1}`,
					title:
						long ||
						[
							'整理本周交付范围',
							'核对组件使用说明',
							'更新团队工作计划',
							'确认页面交互细节'
						][i % 4]!,
					description: '查看任务背景、负责人和计划时间；由宿主决定后续业务操作。',
					status: {
						label: i % 2 ? '待处理' : '进行中',
						tone: i % 2 ? 'warning' : 'primary'
					},
					assignees: [{ id: 'member-lin', name: long || '林知夏' }],
					progress: i === 0 ? 0 : i === 1 ? null : (i * 7) % 100,
					dueAt: i === 2 ? null : '2026-10-19T10:00:00+08:00',
					target: 'task',
					permission: 'read:task'
				})),
				activities: Array.from({ length: 8 }, (_, i) => ({
					id: `activity-${i + 1}`,
					text: `${['林知夏更新了交付说明', '陈雨确认了页面方案', '团队同步了项目进展', '周宁整理了本周计划'][i % 4]}`,
					at:
						i === 7
							? null
							: `2026-10-18T${String(16 - i).padStart(2, '0')}:30:00+08:00`,
					target: 'activity',
					permission: 'read:activity'
				}))
			};
			return config.mode === 'empty'
				? { ...snapshot, metrics: [], shortcuts: [], tasks: [], activities: [] }
				: snapshot;
		}
	};
}

import type { AsamControlSize } from '@asam-ui/ui';
import type { AsamAvatarItem, AsamTaskStatus, AsamTrendProps } from '@asam-ui/pro/components';
import type { RouteLocationRaw } from 'vue-router';

export type WorkbenchId = string | number;
export type WorkbenchFamily = 'minimal' | 'brand' | 'tech';
export interface WorkbenchContext {
	readonly scope: string;
	readonly identity: string;
	readonly revision: string | number;
}
export interface WorkbenchMetric {
	readonly id: WorkbenchId;
	readonly label: string;
	readonly value: number | null;
	readonly unit: string;
	readonly precision?: number;
	readonly helper: string;
	readonly trend?: AsamTrendProps;
}
export interface WorkbenchLink {
	readonly id: WorkbenchId;
	readonly label: string;
	readonly description: string;
	readonly target: string;
	readonly permission?: string;
	readonly hidden?: boolean;
}
export interface WorkbenchTask {
	readonly id: WorkbenchId;
	readonly title: string;
	readonly description: string;
	readonly status: AsamTaskStatus;
	readonly assignees: readonly AsamAvatarItem[];
	readonly progress?: number | null;
	/** ISO 8601 with explicit offset, or null. Display uses configured timeZone. */
	readonly dueAt?: string | null;
	readonly target: string;
	readonly permission?: string;
}
export interface WorkbenchActivity {
	readonly id: WorkbenchId;
	readonly text: string;
	readonly at: string | null;
	readonly target: string;
	readonly permission?: string;
}
export interface WorkbenchSnapshot {
	readonly version: string;
	readonly workspace: {
		readonly title: string;
		readonly description: string;
		readonly name: string;
	};
	readonly metrics: readonly WorkbenchMetric[];
	readonly shortcuts: readonly WorkbenchLink[];
	readonly tasks: readonly WorkbenchTask[];
	readonly activities: readonly WorkbenchActivity[];
}
export interface WorkbenchService {
	load(context: WorkbenchContext & { signal: AbortSignal }): Promise<WorkbenchSnapshot>;
}
/** Adapt the public V2-032 navigate contract; ownership remains with the host. */
export interface WorkbenchNavigator {
	navigate(location: RouteLocationRaw): Promise<boolean>;
}
export interface WorkbenchTarget {
	readonly id: string;
	readonly location: RouteLocationRaw;
	readonly permission?: string;
}
export interface WorkbenchAction {
	readonly id: string;
	readonly label: string;
	readonly permission: string;
	readonly disabled?: boolean;
	readonly hidden?: boolean;
	run(input: WorkbenchContext & { task: WorkbenchTask; signal: AbortSignal }): Promise<void>;
}
export interface WorkbenchHost {
	readonly context: WorkbenchContext;
	readonly service: WorkbenchService;
	readonly navigator: WorkbenchNavigator;
	readonly targets: readonly WorkbenchTarget[];
	readonly actions?: readonly WorkbenchAction[];
	readonly disabled?: boolean;
	readonly readonly?: boolean;
	/** Synchronous host authorization. This is presentation policy, not server authorization. */
	readonly allowed: (permission: string) => boolean;
	/** Can synchronously replace/unmount the host. Rechecked before calling services. */
	readonly onEvent?: (event: WorkbenchEvent) => void;
}
export interface WorkbenchEvent {
	readonly type: 'load' | 'loaded' | 'navigate' | 'action';
	readonly context: WorkbenchContext;
	readonly id?: WorkbenchId;
}
export interface WorkbenchPageProps {
	host: WorkbenchHost;
	size?: AsamControlSize;
	timeZone?: string;
}

.wb {
	--asam-color-text-secondary: var(--asam-color-text-regular);
	--asam-color-surface-info: color-mix(
		in srgb,
		var(--asam-color-primary) 12%,
		var(--asam-color-surface)
	);
	--el-text-color-secondary: var(--asam-color-text-regular);
	color: var(--asam-color-text-primary);
	background: var(--asam-color-surface);
	font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
	font-size: 14px;
	line-height: 1.6;
	min-width: 0;
	overflow-wrap: anywhere;
}
.wb *,
.wb *::before,
.wb *::after {
	box-sizing: border-box;
}
.wb :where(div, section, header, aside, footer, li, dl, dt, dd, p, h1, h2, h3, span, button) {
	min-width: 0;
	max-width: 100%;
}
.wb :focus-visible {
	outline: 2px solid var(--asam-color-primary);
	outline-offset: 3px;
}
.wb h1 {
	margin: 8px 0 16px;
	font-size: clamp(30px, 3.3vw, 44px);
	line-height: 1.2;
}
.wb h2 {
	font-size: 20px;
	margin: 0 0 20px;
	line-height: 1.4;
}
.wb p {
	margin: 8px 0;
}
.wb ul,
.wb ol {
	padding: 0;
	list-style: none;
}
.wb-header {
	display: flex;
	align-items: flex-start;
	flex-wrap: wrap;
	justify-content: space-between;
	gap: 24px;
}
.wb-heading {
	flex: 1 1 280px;
}
.wb-eyebrow {
	font-size: 12px;
	letter-spacing: 0.1em;
	color: var(--asam-color-text-regular);
}
.wb-identity,
.wb-caption,
.wb-reason {
	color: var(--asam-color-text-regular);
	font-size: 13px;
}
.wb-refresh {
	flex: 0 1 240px;
}
.wb-refresh p {
	font-size: 13px;
}
.wb-notice,
.wb-feedback {
	flex-basis: 100%;
}
.wb-notice {
	padding: 12px;
	border-left: 3px solid var(--asam-color-primary);
	background: var(--asam-color-surface-muted);
}
.wb-feedback:empty {
	display: none;
}
.wb-metrics {
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	gap: 16px;
}
.wb-section-title {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	gap: 16px;
	flex-wrap: wrap;
}
.wb-filter {
	display: grid;
	gap: 8px;
	max-width: 380px;
}
.wb-task-grid {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 16px;
	margin-top: 20px;
}
.wb-task-operations {
	display: flex;
	flex-wrap: wrap;
	gap: 8px;
	align-items: center;
}
.wb-task-operations .wb-reason {
	flex-basis: 100%;
}
.wb-shortcut-grid {
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	gap: 24px 16px;
	margin: 0;
}
.wb-shortcut-grid li {
	padding-bottom: 12px;
}
.wb-link-symbol {
	display: block;
	font-size: 26px;
	color: var(--asam-color-primary);
}
.wb-shortcut-grid p {
	font-size: 13px;
}
.wb-timeline {
	margin: 0;
}
.wb-timeline li {
	display: flex;
	gap: 12px;
	margin-bottom: 24px;
}
.wb-timeline-dot {
	width: 8px;
	flex: 0 0 8px;
	height: 8px;
	border: 2px solid var(--asam-color-primary);
	margin-top: 16px;
}
.wb-footer {
	margin-top: 48px;
	border-top: 1px solid var(--asam-color-border);
	padding-top: 20px;
	color: var(--asam-color-text-regular);
	font-size: 12px;
}
.wb > section,
.wb > div:not(.wb-editorial-rule, .wb-tech-masthead) {
	animation: wb-enter 220ms cubic-bezier(0.2, 0.7, 0.3, 1) both;
}
.wb .el-button {
	max-width: 100%;
	white-space: normal;
	height: auto;
	min-height: var(--el-component-size);
}
.wb .el-button > span {
	overflow-wrap: anywhere;
	white-space: normal;
}
.wb .asam-list-meta > div {
	min-width: 0;
}

/* TaskCard owns its avatar composition; tune the upstream public CSS variables
   in this page only so abbreviated member names remain readable in both modes. */
.wb .asam-pro-avatar-group .el-avatar {
	--el-avatar-bg-color: var(--asam-color-surface-muted);
	--el-avatar-text-color: var(--asam-color-text-primary);
}
@keyframes wb-enter {
	from {
		transform: translateY(6px);
		opacity: 0.7;
	}
	to {
		transform: translateY(0);
		opacity: 1;
	}
}
@media (width <= 650px) {
	.wb-metrics {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
	.wb-task-grid {
		grid-template-columns: minmax(0, 1fr);
	}
	.wb-header {
		gap: 16px;
	}
	.wb-refresh {
		flex-basis: 100%;
	}
}
@media (prefers-reduced-motion: reduce) {
	.wb > section,
	.wb > div {
		animation: none !important;
	}
	.wb * {
		scroll-behavior: auto;
		transition: none !important;
	}
}

import type { AsamI18n } from '@asam-ui/ui/i18n';
import type {} from './i18n/Parameters.js';
import {
	createAsamMessageIssue,
	createAsamMessageError,
	formatFieldIssue,
	formatFieldError
} from '@asam-ui/pro/i18n';
import { computed, nextTick, readonly, ref, shallowRef, watch } from 'vue';
import type {
	WorkbenchAction,
	WorkbenchContext,
	WorkbenchHost,
	WorkbenchSnapshot,
	WorkbenchTask
} from './Types.js';

const contextKey = (c: WorkbenchContext) => JSON.stringify([c.scope, c.identity, c.revision]);
const message = (e: unknown) => (e instanceof Error ? e.message : '操作失败，请重试');
const stableId = (v: unknown) =>
	(typeof v === 'string' && !!v.trim()) || (typeof v === 'number' && Number.isFinite(v));

/** Reject a malformed whole snapshot rather than mixing partial data with another identity. */
export function validateSnapshot(input: WorkbenchSnapshot): WorkbenchSnapshot {
	if (
		!input ||
		typeof input.version !== 'string' ||
		!input.version.trim() ||
		!input.workspace ||
		!['title', 'name', 'description'].every(
			(k) => typeof Reflect.get(input.workspace, k) === 'string'
		)
	)
		throw createAsamMessageError(
			'工作台快照缺少版本或工作空间信息',
			'app.templates.workbench.snapshotInvalid'
		);
	for (const rows of [input.metrics, input.shortcuts, input.tasks, input.activities]) {
		if (!Array.isArray(rows))
			throw createAsamMessageError(
				'工作台区块必须是数组',
				'app.templates.workbench.blocksInvalid'
			);
		const ids = new Set();
		for (const row of rows) {
			const key = JSON.stringify([typeof row?.id, row?.id]);
			if (!row || !stableId(row.id) || ids.has(key))
				throw createAsamMessageError(
					'区块标识非法或重复',
					'app.templates.workbench.idsInvalid'
				);
			ids.add(key);
		}
	}
	for (const m of input.metrics)
		if (
			(m.value !== null && typeof m.value !== 'number') ||
			typeof m.unit !== 'string' ||
			typeof m.label !== 'string'
		)
			throw createAsamMessageError('指标格式无效', 'app.templates.workbench.metricInvalid');
	for (const row of [...input.shortcuts, ...input.tasks, ...input.activities])
		if (typeof row.target !== 'string' || !row.target.trim())
			throw createAsamMessageError('目标标识不能为空', 'app.templates.workbench.targetEmpty');
	for (const task of input.tasks)
		if (
			typeof task.title !== 'string' ||
			!task.status ||
			typeof task.status.label !== 'string' ||
			!Array.isArray(task.assignees)
		)
			throw createAsamMessageError('任务格式无效', 'app.templates.workbench.taskInvalid');
	// Own immutable plain data; hosts may reuse/mutate their original object after resolving.
	const copy = structuredClone(input);
	function freeze(o: object) {
		Object.freeze(o);
		for (const v of Object.values(o)) if (v && typeof v === 'object') freeze(v);
	}
	freeze(copy);
	return copy;
}

/** Local current-snapshot orchestration only. No copied list engine and no borrowed disposal. */
export function createWorkbench(getHost: () => WorkbenchHost) {
	const snapshot = shallowRef<WorkbenchSnapshot | null>(null);
	const loading = ref(false),
		error = ref(''),
		feedback = ref(''),
		filter = ref('');
	const busy = ref('');
	const errorCause = shallowRef<unknown>();
	const feedbackDisplay = shallowRef<(scope: AsamI18n) => string>();
	function setFeedback(issue: { readonly message: string }) {
		feedback.value = issue.message;
		feedbackDisplay.value = (scope) => formatFieldIssue(issue, scope);
	}
	function failedFeedback(cause: unknown, kind: 'navigationFailed' | 'actionFailed') {
		const raw = message(cause);
		feedback.value = kind === 'navigationFailed' ? `导航失败：${raw}` : `扩展动作失败：${raw}`;
		feedbackDisplay.value = (scope) =>
			scope.enabled.value
				? scope.t(
						kind === 'navigationFailed'
							? 'app.templates.workbench.navigationFailed'
							: 'app.templates.workbench.actionFailed',
						{
							message:
								cause instanceof Error
									? formatFieldError(cause, scope)
									: scope.t('app.templates.workbench.operationFailed')
						}
					)
				: feedback.value;
	}
	let disposed = false,
		generation = 0,
		request = 0,
		navigationOperation = 0,
		actionOperation = 0;
	let readAbort: AbortController | undefined, actionAbort: AbortController | undefined;
	const valid = (g: number) => !disposed && g === generation;
	const currentContext = () => ({ ...getHost().context });
	const snapshotKey = ref('');
	const ready = () => !!snapshot.value && snapshotKey.value === contextKey(getHost().context);
	function notify(type: 'load' | 'loaded' | 'navigate' | 'action', id?: string | number) {
		const callback = getHost().onEvent;
		if (!callback) return;
		callback({ type, context: currentContext(), id });
		// A parent can replace props in this callback. Vue commits that replacement in
		// its queued render flush; observe it before touching a borrowed service.
		return nextTick();
	}
	function permission(p?: string) {
		try {
			return !p || getHost().allowed(p) === true;
		} catch {
			return false;
		}
	}
	function linkFailure(target: string, p?: string) {
		if (disposed)
			return createAsamMessageIssue('工作台已卸载', 'app.templates.workbench.unmounted');
		if (getHost().disabled)
			return createAsamMessageIssue(
				'工作台已禁用，保留内容供阅读',
				'app.templates.workbench.disabled'
			);
		if (!ready())
			return createAsamMessageIssue(
				'当前身份数据尚未就绪',
				'app.templates.workbench.notReady'
			);
		const matches = getHost().targets.filter((t) => t.id === target);
		if (matches.length !== 1 || !validLocation(matches[0]!.location))
			return createAsamMessageIssue(
				'目标未注册或位置无效',
				'app.templates.workbench.targetInvalid'
			);
		if (!permission(p) || !permission(matches[0]!.permission))
			return createAsamMessageIssue(
				'当前权限不允许访问',
				'app.templates.workbench.accessDenied'
			);
		return undefined;
	}
	function actionFailure(action: WorkbenchAction) {
		if (getHost().disabled || !ready() || disposed)
			return createAsamMessageIssue(
				'工作台尚不可操作',
				'app.templates.workbench.unavailable'
			);
		if (getHost().readonly)
			return createAsamMessageIssue(
				'只读工作台不允许写扩展动作',
				'app.templates.workbench.readonly'
			);
		if (!permission(action.permission))
			return createAsamMessageIssue(
				'当前权限不允许此动作',
				'app.templates.workbench.actionDenied'
			);
		if (action.disabled)
			return createAsamMessageIssue(
				'宿主已禁用此动作',
				'app.templates.workbench.actionDisabled'
			);
		return undefined;
	}
	function linkReason(target: string, p?: string, scope?: AsamI18n) {
		const reason = linkFailure(target, p);
		return reason ? formatFieldIssue(reason, scope) : '';
	}
	function actionReason(action: WorkbenchAction, scope?: AsamI18n) {
		const reason = actionFailure(action);
		return reason ? formatFieldIssue(reason, scope) : '';
	}
	async function refresh() {
		if (disposed || getHost().disabled) return false;
		const g = generation,
			token = ++request;
		readAbort?.abort();
		const abort = new AbortController();
		readAbort = abort;
		const host = getHost(),
			context = currentContext();
		loading.value = true;
		error.value = '';
		errorCause.value = undefined;
		try {
			const notification = notify('load');
			if (notification) await notification;
			if (!valid(g) || token !== request || getHost().disabled) return false;
			const result = await host.service.load({ ...context, signal: abort.signal });
			if (!valid(g) || token !== request || abort.signal.aborted) return false;
			snapshot.value = validateSnapshot(result);
			snapshotKey.value = contextKey(context);
			const loaded = notify('loaded');
			if (loaded) await loaded;
			return valid(g) && token === request;
		} catch (e) {
			if (valid(g) && token === request && !abort.signal.aborted) {
				error.value = message(e);
				errorCause.value = e;
			}
			return false;
		} finally {
			if (valid(g) && token === request) loading.value = false;
		}
	}
	async function navigate(target: string, p?: string) {
		const g = generation,
			token = ++navigationOperation;
		feedback.value = '';
		feedbackDisplay.value = undefined;
		try {
			let reason = linkFailure(target, p);
			if (reason) {
				setFeedback(reason!);
				return false;
			}
			if (!valid(g)) return false;
			const notification = notify('navigate', target);
			if (notification) await notification;
			if (!valid(g) || token !== navigationOperation) return false;
			reason = linkFailure(target, p);
			if (reason || !valid(g)) {
				if (valid(g)) setFeedback(reason!);
				return false;
			}
			const host = getHost(),
				location = host.targets.find((t) => t.id === target)!.location;
			const success = await host.navigator.navigate(location);
			if (!valid(g) || token !== navigationOperation || linkReason(target, p)) return false;
			setFeedback(
				success
					? createAsamMessageIssue('已打开目标页面', 'app.templates.workbench.opened')
					: createAsamMessageIssue(
							'导航已取消或被守卫拒绝，请重试',
							'app.templates.workbench.cancelled'
						)
			);
			return success;
		} catch (e) {
			if (valid(g) && token === navigationOperation) failedFeedback(e, 'navigationFailed');
			return false;
		}
	}
	async function runAction(task: WorkbenchTask, id: string) {
		if (busy.value) return false;
		const g = generation,
			token = ++actionOperation;
