	const name = Reflect.get(location, 'name'),
		path = Reflect.get(location, 'path');
	if (path !== undefined)
		return (
			typeof path === 'string' &&
			path.startsWith('/') &&
			!path.startsWith('//') &&
			!path.includes('://')
		);
